95	export function exportCommand(program: Command) {
96	  const exportCmd = program.command('export').description('Export eval records or logs');
97	
98	  exportCmd
99	    .command('eval <evalId>')
100	    .description('Export an eval record to a JSON file')
101	    .option('-o, --output [outputPath]', 'Output path for the exported file')
102	    .action(async (evalId, cmdObj) => {
103	      try {
104	        let result;
105	        if (evalId === 'latest') {
106	          result = await Eval.latest();
107	        } else {
108	          result = await Eval.findById(evalId);
109	        }
110	
111	        if (!result) {
112	          logger.error(`No eval found with ID ${evalId}`);
113	          process.exitCode = 1;
114	          return;
115	        }
116	
117	        if (cmdObj.output) {
118	          await writeOutput(cmdObj.output, result, null);
119	
120	          logger.info(`Eval with ID ${evalId} has been successfully exported to ${cmdObj.output}.`);
121	        } else {
122	          const summary = await result.toEvaluateSummary();
123	          const metadata = createOutputMetadata(result);
124	          const jsonData = JSON.stringify(
125	            {
126	              evalId: result.id,
127	              results: summary,
128	              config: result.config,
129	              shareableUrl: null,
130	              metadata,
131	            },
132	            null,
133	            2,
134	          );
135	          logger.info(jsonData);
136	        }
137	
138	        telemetry.record('command_used', {
139	          name: 'export',
140	          evalId,
141	        });
142	      } catch (error) {
143	        logger.error(`Failed to export eval: ${error}`);
144	        process.exitCode = 1;
145	      }
146	    });
147	
148	  exportCmd
149	    .command('logs')
150	    .description('Collect and zip log files for debugging')
151	    .option('-n, --count <number>', 'Number of recent log files to include (default: all)')
152	    .option('-o, --output [outputPath]', 'Output path for the compressed log file')
153	    .action(async (cmdObj) => {
154	      try {
155	        const logDir = getLogDirectory();
156	
157	        if (!fs.existsSync(logDir)) {
158	          logger.error(
159	            `No log directory found. Logs are created when running commands like "promptfoo eval".\nLog directory: ${logDir}`,
160	          );
161	          process.exitCode = 1;
162	          return;
163	        }
164	
165	        const allLogFiles = getLogFilesSync();
166	
167	        if (allLogFiles.length === 0) {
168	          logger.error(
169	            `No log files found in the logs directory. Logs are created when running commands like "promptfoo eval".\nLog directory: ${logDir}`,
170	          );
171	          process.exitCode = 1;
172	          return;
173	        }
174	
175	        // Determine how many files to include
176	        let logFiles = allLogFiles;
177	        if (cmdObj.count) {
178	          const count = parseInt(cmdObj.count, 10);
179	          if (isNaN(count) || count <= 0) {
180	            logger.error('Count must be a positive number');
181	            process.exitCode = 1;
182	            return;
183	          }
184	          logFiles = allLogFiles.slice(0, count);
185	        }
186	
187	        // Determine output path
188	        let outputPath = cmdObj.output;
189	        if (!outputPath) {
190	          const timestamp = new Date()
191	            .toISOString()
192	            .replace(/[:.]/g, '-')
193	            .replace('T', '_')
194	            .split('.')[0];
195	          outputPath = `promptfoo-logs-${timestamp}.gz`;
196	        }
197	
198	        // Ensure output path has .gz extension
199	        if (!outputPath.endsWith('.gz')) {
200	          outputPath += '.gz';
201	        }
202	
203	        logger.info(`Collecting ${logFiles.length} log file(s)...`);
204	
205	        // Create the compressed archive
206	        await createLogArchive(
207	          logFiles.map((f) => f.path),
208	          outputPath,
209	        );
210	
211	        logger.info(`Log files have been collected in: ${outputPath}`);
212	        logger.info('You can now share this file for debugging purposes.');
213	
214	        telemetry.record('command_used', {
215	          name: 'logs',
216	          fileCount: logFiles.length,
217	        });
218	      } catch (error) {
219	        logger.error(`Failed to collect logs: ${error}`);
220	        process.exitCode = 1;
221	      }
222	    });
223	}
